    if (n &lt; 1) throw new IllegalArgumentException();
    var m = (n + 1)/2;
    if (n &gt; 1) {
        System.out.print(m + &quot; &quot;);
        if (n &gt; 2) writeSequence(n - 2);
        System.out.print(m + &quot; &quot;);
    }
    else System.out.print(m + &quot; &quot;);
}
</code></pre>
